delete from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom';

insert into sermons (service_date, title, preacher, is_guest, occasion, series, anchor_scripture, thesis, summary, youtube_url, notes)
values (
  '2026-08-09',
  'Enter Into The Kingdom',
  'Rev Ifeayinchukwu Obi',
  true,
  null,
  null,
  'Matthew 13:44',
  'Entering the kingdom - letting Christ actually rule every decision - is the pathway to the abundant life Jesus promised. The kingdom is of inestimable value, it is hidden until you look for it, and the man who finds it sells everything he has for joy, not for duty.',
  'Guest minister Rev Ifeayinchukwu Obi, preaching what he calls the message he brought from Nigeria, takes John 10:10 and asks the congregation a direct question: do you actually live in abundance? He opens by having the room sing and proclaim Psalm 95:3 - the Lord is a great God and a great King above all gods - and presses the point that a king in a true kingdom takes care of everything concerning his citizens so that they can serve him, which is what it means to call Christ King. He defines abundant life from 2 Corinthians 9:8, read aloud four times by four different people, so that all grace abounds and you have sufficiency in all things and abound to every good work. He compares that with the Google definition the congregation reads out, and approves of the phrase not just in material wealth. From there he moves through Isaac carrying the wood up Moriah, looking for the sacrifice while he is the sacrifice, as a type of Christ, and into Romans 12:1: present your bodies a living sacrifice, so that every single decision is made for Christ rather than for yourself. Kingdom, he explains, means king''s dominion, and Jesus located that dominion inside you - so the will of God has to be done in you first before it is done in the church, and every believer is a vessel of the kingdom''s expansion. Matthew 6:33 makes the kingdom the priority; Matthew 13:44 gives the response - a man finds treasure hidden in a field, hides it again, and for joy sells everything he has to buy the field, while the rich young ruler walks away sorrowful because he cannot see that it was abundant life calling him. Righteousness, he says, is simply acting as the King demands: if work wants you to lie, you refuse, even if they sack you, and it is only looking back that you see God. He closes on becoming like a child, completely dependent, and on repentance as changing your mind - letting the kingdom become your new paradigm of life rather than wallowing in what he calls the wilderness of Christianity.',
  'https://www.youtube.com/watch?v=90OKuTX7a1M',
  'SOURCE: near-verbatim transcript of the sermon section only (49:37 to 1:43:17 of the full service recording), supplied by Bolaji on 9 August 2026. Congregation readings and his asides are included. SCRIPTURE CORRECTIONS - four references he gave aloud are wrong and are corrected in this record; do NOT caption the spoken versions. (1) He says Ecclesiastes 8:12 for money is a defence, wisdom is a defence - it is Ecclesiastes 7:12. (2) He says Galatians chapter 2:2 for the life I now live - it is Galatians 2:20. (3) Brother Dobby says directing your pathway is an auto-transcript garble of Proverbs 3:6. (4) 2 Corinthians 9:8 is correct as given. SERVICE SCRIPTURE DISCREPANCY: the order of service listed the pre-sermon reading as Matthew 23:44-45, which does not exist - Matthew 23 ends at verse 39. He preached Matthew 13:44, the parable of the treasure hid in a field, which is what the sermon is built on. The Sunday pack, briefing and Control Room were all seeded as Matthew 13:44-45 and this is now confirmed correct by the transcript. He also opened on Psalm 95:3, which did not appear in the order of service at all. NAME: spelled Ifeayinchukwu per the order of service, the run sheet and the sermon thumbnail. It has also appeared as Ifeanyichukwu (21 June 2026). STILL UNCONFIRMED - settle before this name goes anywhere further. TRANSCRIPT GARBLES corrected in full_text: Jehovah Gy to Jehovah Jireh, God gutter to Golgotha, Mount Mariah to Moriah, syncreticism to syncretism, suck you to sack you. TIMING: he was given 40 minutes, repeatedly noted the clock, and ran roughly two minutes over. TIMESTAMP OFFSET: the sermon-only MP4 runs about 49 minutes behind the full service recording - add 49:06 to an MP4 timestamp to get the YouTube position.'
);


-- ============================================================
-- PART 2 of 4 - the sermon body (one long E'' string, own statement)
-- ============================================================

update sermons
   set full_text = E'CLEANED TRANSCRIPT (sermon only, 49:37 to 1:43:17 of the service recording). Auto-transcript garbles corrected; scripture references he mis-cited are corrected in square brackets. Congregation readings shown where they carry the text.\n\nOPENING - PSALM 95:3 AS PROCLAMATION\nThank you, Pastor. Good morning. Who''s my timekeeper? Tell me when I have only 10 minutes left.\nPsalm 95:3. We''ve sung it before here, so join me to sing it again. For the Lord is a great God, and a great King above all gods. As we sing it, you''re actually proclaiming it. I want you to proclaim it by yourself. It''s not just a song, it''s a proclamation of where you stand with this God. It''s my way of proclaiming the name of Jesus all over this place, so that He''ll be pre-eminent, especially over my heart, in these 40 minutes. Proclaim Him King over your life, especially in this hour, so that when you hear the word, the word will find faith in your heart, and when I speak, I will speak from Him and not just my words.\nHeavenly Father, that is our declaration this morning. You are a great God. You are a great King above all gods. We worship and we adore you.\n\nWHY THE PSALM FIRST\nI tell you why I take that psalm before I start something like this. Because the One that is in me is real. And when I have a testimony from inside my heart that He''s with me, my feet begin to dance. Even by the second stanza of that psalm, my heart begins to dance and my feet begin to dance. Try that song in your private capacity. Sing it a minute. You will see the One who lives inside you begin to dance in your heart. And when He begins to dance inside your heart, your feet will correspond, because it is a proclamation of the reality of the child of God. It''s not only in church that you worship Him. You can worship Him in your private capacity.\n\nWHAT THE VERSE IS SAYING - A KING RULES\nWho is the Lord? Jesus Christ of Nazareth. He''s our Lord, our Saviour, our Redeemer. The psalmist is telling us He''s a great God. But people just say God, because there is God. Many people say God, so they say God. They don''t really understand what it means to have someone who is a God to you. And he says He''s not only God, He is also a great King. He created all things in the heavens and the earth.\nA king rules. Just like here you have King Charles, but the kingdom here is poor. In the true meaning of a kingdom, the king is in charge of everything concerning your life. The king takes care. Your food, your clothing, your everything, so that you can serve him. That''s what it means to be a citizen of a kingdom. And when we talk about Christ being King, and a great one, you''re telling yourself that He rules over everything that concerns you. Not only you - the whole world, for those who will belong to His kingdom.\n\nTHE SUBJECT - JOHN 10:10\nOur subject today: enter into the kingdom is the pathway to the abundant life. Have you heard about the abundant life? We read John 10:10 this morning. The thief comes to kill, to steal and to destroy. But I have come to give you life, and to give it abundantly. And who is He talking to? He''s talking to you. So my question is: do you have abundant life? Do you live in abundance?\n\n2 CORINTHIANS 9:8 - READ FOUR TIMES\nCan somebody read 2 Corinthians 9:8 for us, preferably from King James. And God is able to make all grace abound toward you, that ye always having all sufficiency in all things may abound to every good work.\nPut it in your head. That''s why we read it so many times, so that it can get into your head. Scriptures are meant to get into your head, because you need to call them up when the time comes. Christians speak their faith. If you don''t speak, check yourself - that''s why you are where you are. Situations face you, you speak what the scripture says about that situation. You speak it to that situation, and that situation hears and obeys. But when you''re quiet, intimidated by the circumstances, you remain intimidated. Christians are speaking people. What you believe in your heart, you speak with your mouth. What shows that you believe is what you say. Christians are professors - they profess what they believe.\n\nDEFINING ABUNDANT LIFE\nLet me take you away from the Bible. Somebody Google abundant life for me. A spiritual state filled with deep peace, purpose, joy, and an internal relationship with God. Anybody a different definition? A life filled with purpose, joy, good relationships, personal growth, health, peace and opportunities. It is about quality of life, not just in material wealth.\nNot just in material wealth. Fantastic. I like that addition, and I like it very much. That''s Google, not Bible, but it''s fairly accurate. And the scripture we read in 2 Corinthians 9:8 says God is able to make all grace abound to you, so that you will have sufficiency in all things, so that you will abound unto every good work. You''re here for work. You''re called Jesus Christ''s co-labourer. He doesn''t send you to war without going with you, because it''s not you that will fight, it''s Him that will fight. If you go alone, the first step you take they will defeat you properly. But when you go with Him, He is your all-sufficiency, because of that grace. He is your grace.\n\nISAAC AND THE LAMB\nWhenever I come here I see so much potential. It''s like Isaac asking his father Abraham: Father, I see the wood, I see the fire, but where is the lamb for sacrifice? This is a teenager going up the hill to be the sacrifice. So what was he looking for? He was looking for the sacrifice when he is the sacrifice. Does that sound like you and I?\nHow did the father answer him? Jehovah Jireh, on the mount of sacrifice. God will provide Himself a lamb. My son, don''t worry, God will provide. Finally on Mount Moriah a ram was substituted for Isaac - not the lamb the father prophesied. A ram is a grown-up sheep that has walked all over the place. But what God was supposed to provide is a pure lamb, an innocent lamb.\nIsaac is a type of Christ. A teenager tied on a rope to be sacrificed, and he didn''t resist. He carried the wood all the way to that mountain. When it dawned on him, he did not resist his father. Father, let your will be done. If this is what you want to do with me, fine. No resistance. The Bible didn''t record that Isaac resisted. Isaac was pointing us to Christ. Christ went to Golgotha carrying His own wood, fully obeying God in spite of the shame, willingly saying: Father, I haven''t come to do my will, it is your will I have come to do.\n\nROMANS 12:1 - THE LIVING DEAD\nI beseech you therefore brethren, by the mercies of God, that you present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.\nMake everything about you a living sacrifice. What''s the practical implication of that? My brothers and my sisters, every single decision you make should never be made for yourself. It should be made for Christ. Because you are dead. You''ve been sacrificed with Christ on the cross. It''s no longer you that live, it''s Christ that lives through you. The life you''re living now belongs to Christ.\nWhen you live in the actuality of who you are, nothing can touch you. I say nothing - whether from the past or from the future. The actuality of a Christian is that that Christian is what is called the living dead. Apostle Paul helps us in Galatians 2:20 [he said Galatians 2:2]: the life that you now live is not your life, it is the life of Christ that you live. So every decision you make, Christ must take the glory.\n\nTHY KINGDOM COME - WHERE THE DOMINION IS\nLet''s recite the Lord''s Prayer. My focus in that recital is where he says thy kingdom come, because it is the kingdom we are looking at as the pathway to abundant life. Thy will be done on earth as it is done in heaven. He''s King in heaven. God is King. No controversy from beginning to end.\nThe meaning of kingdom is king and dominion - two words joined together. King''s dominion. Dominion is where somebody rules. So a kingdom is a dominion where the king rules. And where is that dominion today? Jesus said if they tell you the kingdom of God is here or there, don''t listen to them. Why? Because the kingdom of God is inside you.\nEvery day you come to church, you must receive something that transforms you. If you don''t, you''re on your own. If you just come to church to do religion, you''re on your own. You must demand from the Spirit, from the pastor, from the environment, something from God for you. You come here to be transformed. The more you hear from God, the more you believe, and the more things you are able to realise.\nWhen Christ is ruling in you, and you meet another person where Christ is ruling in them, you have brought the kingdom. Then they can say this church is the kingdom of God. But we can''t say that - because maybe only 10 per cent of people are allowing Christ to rule in them. The more we head towards 80 per cent of us practically allowing Christ to rule in their heart, then this will become a physical kingdom. Not by environment. Not by building. By the hearts that are assembled here.\nYou can make all the difference in this church, if you determine to. If you''re not looking to the worship leader thinking he''s the one that will bring down the Spirit - no, you are the one that is carrying the Spirit. He will do his part, but you will do your part. The will of God has to be done first in you. You are then the one that will carry the will of God to the uttermost ends of the earth. That''s how the kingdom expands. If you''re looking for the expansion of the kingdom, you are one of the vessels that will cause it.\n\nMATTHEW 6:33 - PRIORITY\nBut seek ye first the kingdom of God, and his righteousness, and all these things shall be added unto you.\nWho said that? The Lord Jesus Christ, your Lord, your King, is telling you what should be your priority. Your priority should be the kingdom of God. You should seek it first. Priority one. Your audience is one person: the King. And who is the King? Christ Jesus. Seek where He rules. He rules in your heart. Enthrone Him in your heart concerning everything that you do. Everything. Whether it is a wife to marry, a husband to marry, work to do, a house to build - whatever it is, He will make all grace abound unto you so that you will have all sufficiency in all things, so that you can abound unto every good work.\n\nMATTHEW 13:44 - THE TREASURE IN THE FIELD\nThis is the message I''ve brought from Nigeria to this church. Matthew 13:44. Again, the kingdom of heaven is like unto treasure hid in a field; the which when a man hath found, he hideth, and for joy thereof goeth and selleth all that he hath, and buyeth that field.\nWhat is a treasure? Something valuable. In another version he calls it something of inestimable value - something you can''t put a value to. The value is so great. It has not appeared to man, neither has it entered his ears nor his heart, what God has prepared for those who love Him.\nHidden where? In the field. The kingdom is also hidden. It''s not something people will look at you and see. When a man has found it, what did he do? He hid it. He dug the ground where he found it and covered that treasure, so that nobody else will find it. Then for joy of finding it he went back home, sold everything he had, and bought the field - so that he will have title deed to the land. He will not have to quarrel with anybody about the land, because the treasure is there.\nCan you see the man''s response? For joy. And verse 45 is the same thing with the merchant and the pearl of great price. He sold everything he had just to buy that pearl.\n\nTHE COST - THE RICH YOUNG RULER\nDo you remember the rich young ruler who came to the Lord Jesus Christ? And the Lord told him to go home and sell everything, give to the poor, then come and follow me. The Bible recorded that he was sorrowful. He went away sorrowful. And the Lord said how difficult it is for people with great riches to enter into the kingdom of God.\nEcclesiastes 7:12 [he said Ecclesiastes 8:12]: money is a defence, wisdom is a defence, but the excellency of knowledge is that wisdom gives life. Money does not give life. That rich young ruler did not realise that it was eternal life, abundant life, that was calling him. He thought: I will lose all my money, how can this man be asking me to do this? It was difficult for him.\n\nRIGHTEOUSNESS IS DOING WHAT THE KING SAYS\nWhat is righteousness? Acting according to the word of God. The righteousness of the kingdom is acting as the King demands of you. Like Jesus said to the Father: it''s not my will, it''s your will that I will do. Like Isaac said to Abraham: I''m here, you tie me up, that''s all right, whatever you want to do with me, go ahead.\nBut the point is, do you believe it? Do you believe your King telling you what to do? It''s only when you believe that you will step out to do. When situations face you, you stand on that word and say: Jesus wants me to do this, this is what I will do. Whether you''re at work and they want you to lie - you say no, I will not lie. Whether you sack me from this job, I don''t care. And they will sack you. You wouldn''t even have money to pay the school fees of your children. But suddenly the next month they give you a job that gives you three times the salary of that one, and you look back and say, it''s only God that did that. How, did I leave that job, would I be here today? But it''s only looking back that you will see God. Not when you''re in that situation. In that situation, all you have to do is to do what the King says. Just do what the King says. That''s the righteousness of the kingdom.\n\nENTERING IS NOT INHERITING\nWe have all entered into the kingdom, but you need to inherit the kingdom. If your righteousness does not exceed the righteousness of the scribes and the Pharisees - what is that like? They say things they want you to do, but they themselves don''t do it. If your righteousness does not exceed that, you cannot inherit the kingdom.\nIn another place He says if you''re not converted and become like a child, you cannot inherit the kingdom. What is the characteristic of a child? A child is completely dependent on the parents. What the parents say, they do. I''m not talking about the Western child where the parent expects the child to lead himself. A child is completely dependent on the parents. The parents are the guide, and he does it completely dependent, no question about it.\n\nTHAT IS THE PATHWAY\nThat is the pathway to the abundant life. Christ will make all grace abound unto you so that you will have sufficiency in - not some things, not some physical things, not some spiritual things - all things.\nIf you don''t live in it, you don''t experience it. Don''t look at people and say, oh that pastor, poor pastor, I can''t be like him. That''s your problem. You''re not that pastor. That pastor has a pathway that Christ is making him follow. You have your own pathway, and it''s only your pathway that you will follow. If you acknowledge Christ in everything that you do, He says He will direct your pathway [Proverbs 3:6]. God will bring the pathway you will tread in front of you. You won''t make any mistake of choice.\n\nTHE CALL - WHAT IS YOUR RESPONSE?\nWhat have you heard from me today? Look at the response of the man who found the kingdom. This is the message I brought to you from Nigeria. If you miss it, you''ve missed the heart of God today. In Matthew 13:44 the response of that man was a response of joy. Joy that he found the kingdom.\nWhat is your response, that you are in the midst of the people carrying the kingdom of God? You come to church every Sunday. What is your response? Is it true joy? Do you have true joy in your heart? Be realistic. Have you prioritised the kingdom of God over every decision that you take? Every decision - not some decisions, not spiritual, not physical - all decisions you take give you an opportunity to enter into the kingdom. How you bring up your child, the choices you make in society, the places that you go, the things that you do: are those the things the King wants you to do?\nWhen John the Baptist came he said the kingdom is coming near, you have to change your mind. When the Lord Jesus Christ came He said the kingdom is here, you have to change your mind. Have you changed your mind about the things of the kingdom? I have changed my mind since 27 July 1987. I stopped walking in the wilderness of Christianity. Many of us are still wallowing in the wilderness of Christianity, looking at other people, looking at other things, instead of concentrating on the King and what the King says.\nIt is you that the will of God will be done in, first, before it is done in this church. You are the one that will bring the will of God into this place, and all together you will march out to the streets of Manchester to the uttermost ends of the earth. But it starts with you.\nIf you need to repent before God, please repent. What do we mean by repent? Change your mind. What''s your paradigm of life? Change it to the kingdom paradigm. Let the kingdom become your new paradigm of life. Are you mixing the kingdom of God with so many things? That''s called syncretism. In Nigeria some people will tie juju things on their wrist, cover it with a jacket, and they are in church. The dependency is not on God. It doesn''t have to be idols that you tie by your waist. It can be other things that distract you from the will of God for your life, for your family, for your church.\n\nTHE VALUE OF YOUR SOUL\nThe Lord Jesus Christ says: what will it benefit you if you receive the whole world and you lose your soul? Jesus is telling you the value of your soul. The value of your soul to Jesus Christ is greater than the whole world. Can you put a value to the whole world? Your soul, Jesus is saying, is greater in value to Him than the whole world. Can you imagine then what He is telling you about the inestimable value of the kingdom of God? Is it because you cannot conceptualise it that you think it''s nothing?\nRepent. Change your mind. Tell God from today He should forgive you. Ask Him to help you. It''s not by power, it''s not by might, it''s by His Spirit. And His Spirit is already in you. But you need to know that. The Spirit is ready to guide you, ready to lead you, only if you wait on Him. Are you impatient with the things of God? Do you relegate the things of the kingdom to nothingness? You think it''s for weak people, that church is for people who have problems? You need to change your mind.\nThe King of the kingdom is resident in your heart, waiting to guide you in every decision that you make in life, so that you will have abundance in all things, so that you do what He wants you to do. He''s the King of all the earth. He owns the cattle upon a thousand hills. The gold and the silver belong to Him. Why should your case be different? You are the one holding your case. You''re the one refusing to do what He wants you to do. Therefore He''s not ruling in your heart. He wants to rule in your heart. That''s where His ruling begins. He''s there already.\n\nCLOSING PRAYER\nPrecious Father, we thank you. You said you will show mercy to whom you will show mercy, because you are a gracious God. Father, we pray that you will cause all grace to abound unto us, that we all will have sufficiency in all things, and we will abound unto every good work that you have planned for us to do, that will bring praise and glory to your holy name. We pray in Jesus'' name. Amen.'
 where service_date = '2026-08-09' and title = 'Enter Into The Kingdom';


-- ============================================================
-- PART 3 of 4 - the 16-point outline
-- ============================================================
delete from sermon_points where sermon_id = (select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom');
insert into sermon_points (sermon_id, position, heading, detail, scriptures)
values
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 1, 'A king rules everything, or he is not your king', 'Psalm 95:3 sung and proclaimed by the whole room before he preaches a word, because he wants the congregation standing on it rather than just hearing it. A king in a true kingdom is in charge of everything concerning your life - your food, your clothing, everything - so that you can serve him. He contrasts it with King Charles, whose kingdom he calls poor. Calling Christ King therefore means saying He rules over everything that concerns you.', '{"Psalm 95:3"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 2, 'The question the sermon turns on: do you actually live in abundance?', 'John 10:10 was the reading. The thief comes to kill, steal and destroy; Jesus came to give life and give it abundantly. He puts it directly to the room rather than leaving it theoretical: do you have abundant life, do you live in abundance?', '{"John 10:10"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 3, 'Abundant life defined, and it is not mainly about money', '2 Corinthians 9:8 read aloud four times by four different people, deliberately, so it lodges. All grace abounds so you have sufficiency in all things and abound to every good work. He has the congregation read out Google''s definition too, and singles out the phrase not just in material wealth for approval. The sufficiency is for work, because you are a co-labourer and He does not send you to war without going with you.', '{"2 Corinthians 9:8","John 10:10"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 4, 'Scripture is for speaking, not storing', 'Christians speak their faith. If you do not speak, check yourself - that is why you are where you are. Situations face you and you speak what Scripture says to that situation, and it hears and obeys. Stay quiet and intimidated and you remain intimidated. Christians are professors: they profess what they believe.', '{}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 5, 'Isaac looked for the sacrifice while he was the sacrifice', 'A teenager carrying the wood up Moriah, asking where the lamb is. Does that sound like you and I? Abraham answers Jehovah Jireh - God will provide Himself a lamb. A ram is substituted, not the lamb prophesied, because the lamb is Christ. Isaac is a type of Christ: tied, not resisting, carrying his own wood, saying let your will be done. Christ carried His own wood to Golgotha in the same posture.', '{"Genesis 22:7-8"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 6, 'The living dead: every decision belongs to Christ', 'Romans 12:1, present your bodies a living sacrifice. The practical implication is blunt - every single decision you make should never be made for yourself, it should be made for Christ, because you are already dead and sacrificed with Him. Galatians 2:20: the life you now live is not yours. He calls the Christian the living dead, and says that when you live in the actuality of that, nothing can touch you.', '{"Romans 12:1","Galatians 2:20"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 7, 'Kingdom means king''s dominion, and the dominion is inside you', 'Two words joined. Jesus told them not to chase reports of the kingdom being here or there, because it is inside you. Therefore the will of God has to be done in you first, before it is done in the church. When Christ rules in you and you meet someone He also rules, you have brought the kingdom.', '{"Luke 17:21"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 8, 'Only about ten per cent - a challenge to the room', 'He says this church cannot yet be called a kingdom because perhaps only ten per cent are allowing Christ to rule in them; nearer eighty per cent and it becomes a physical kingdom. Not by building or environment, but by the hearts assembled. And do not look to the worship leader to bring the Spirit down - you are the one carrying the Spirit, he does his part and you do yours.', '{}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 9, 'Seek first: the kingdom is the priority, not an item on the list', 'Matthew 6:33. Your audience is one person, the King. Enthrone Him in your heart concerning everything you do - a wife, a husband, work, a house, whatever it is - and all these things will be added.', '{"Matthew 6:33"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 10, 'The treasure hid in a field, and the joy of the man who found it', 'Matthew 13:44, read aloud line by line with the congregation. Treasure of inestimable value, hidden, found by a man who was looking. He hides it again, and for joy sells everything he has and buys the field, so he holds the title deed and need not quarrel with anyone. Verse 45 repeats it with the merchant and the pearl of great price. The response he wants noticed is joy, not duty.', '{"Matthew 13:44","Matthew 13:45-46"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 11, 'The rich young ruler could not see what was calling him', 'Told to sell everything and follow, he went away sorrowful. Money is a defence and wisdom is a defence, but the excellency of knowledge is that wisdom gives life - money does not give life. He did not realise it was eternal, abundant life calling him. He only saw what he was losing.', '{"Ecclesiastes 7:12","Matthew 19:21-22"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 12, 'Righteousness is doing what the King says, at cost', 'The sermon''s sharpest illustration. If work wants you to lie, you say no, I will not lie, whether you sack me or not. And they will sack you, and you may not have school fees. Then the next month a job at three times the salary, and looking back you see God. But it is only looking back that you see Him - in the situation, all you do is what the King says.', '{}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 13, 'Entering is not the same as inheriting', 'Righteousness must exceed that of the scribes and Pharisees, who say what others should do and do not do it themselves. And unless you are converted and become like a child you cannot inherit the kingdom. A child is completely dependent on the parents - not the Western child expected to lead himself, but complete dependence, no question about it.', '{"Matthew 5:20","Matthew 18:3"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 14, 'Your pathway is yours, not the pastor''s', 'Do not look at a pastor and conclude you cannot be like him. That pastor has a pathway Christ is making him follow; you have your own, and it is only yours you will walk. Acknowledge Christ in everything and He will direct your pathway, laying it out in front of you so you make no mistake of choice.', '{"Proverbs 3:6"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 15, 'Repent means change your mind, and syncretism is the trap', 'John the Baptist and Jesus both said change your mind. He dates his own to 27 July 1987, and says he stopped walking in what he calls the wilderness of Christianity - where many are still wallowing, looking at other people instead of the King. Mixing the kingdom with other dependencies is syncretism: juju tied on the wrist under a jacket, or anything else that distracts from the will of God.', '{"Matthew 3:2","Matthew 4:17"}'::text[]),
    ((select id from sermons where service_date = '2026-08-09' and title = 'Enter Into The Kingdom'), 16, 'The value of your soul against the whole world', 'What will it benefit you if you gain the whole world and lose your soul? Your soul is worth more to Christ than the whole world - so consider what that says about the inestimable value of the kingdom. The King is already resident in your heart, waiting to guide every decision. You are the one holding your case.', '{"Mark 8:36"}'::text[]);


